var t=`1051-martabak-manis`;var s=`world-1051`;var a=`ID`;var n=`southeast-asia`;var r=8;var o=34;var h={en:`Martabak Manis`,ua:`Мартабак маніс`};var l={en:`Martabak Manis is a dish from Indonesia prepared with all-purpose flour, whole cow milk, instant yeast, chicken egg. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Мартабак маніс, страва кухні країни Індонезія, яку готують із таких продуктів: пшеничне борошно універсальне, цільне коров'яче молоко, інстантні дріжджі, куряче яйце. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var g=[{en:`Whisk the listed batter ingredients until smooth. Let the mixture rest briefly so the flour hydrates.`,ua:`Збийте складники рідкого тіста до однорідності. Дайте суміші коротко відпочити, щоб борошно увібрало вологу.`,t:[`mixing`,`whisking`],m:12,i:[[`all-purpose-flour`,250,`g`],[`whole-cow-milk`,230,`ml`],[`instant-yeast`,4,`g`],[`white-granulated-sugar`,45,`g`],[`chicken-egg`,2,`pcs`]]},{en:`Bake in a preheated 180°C oven for about 14 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 14 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:14,i:[[`unsalted-butter`,45,`g`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`chocolate-chips`,115,`g`],[`peanut`,100,`g`],[`sweetened-condensed-milk`,100,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cheddar-cheese`,80,`g`]]}];var d={slug:t,id:s,country:`ID`,region:n,servings:8,minutes:34,title:h,text:l,steps:g};export{a as country,d as default,s as id,o as minutes,n as region,r as servings,t as slug,g as steps,l as text,h as title};